   * Returns a function that validates, normalizes, and tokenizes values.
   * @throws IllegalArgumentException if validation fails
   */
  def build(): T => Token = { value =>
    // Validate
    validators.foreach { validator =>
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for $value")
      }
    }

    // Convert to string
    var strValue = value.toString

    // Normalize
    normalizers.foreach { normalizer =>
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenTypeString, metadata)
