/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This Scala implementation translates the Python tokenizer module to idiomatic Scala,
 * leveraging Scala's type system for type safety and using functional programming patterns.
 *
 * Key design decisions:
 * - Sealed traits for algebraic data types (TokenType)
 * - Case classes for immutable data structures (Token)
 * - Abstract traits with generics for extensible tokenizer hierarchy
 * - Pattern matching for runtime type dispatch (replacing Python's isinstance checks)
 * - Option/Either for error handling (replacing exceptions)
 * - Variance annotations for generic type safety
 */

import scala.collection.mutable
import scala.math.BigDecimal
import scala.util.Try
import java.time.LocalDate
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

// ============================================================================
// Token Type Enumeration
// ============================================================================

/**
 * Sealed trait representing token types.
 * Using sealed trait for exhaustive pattern matching and extensibility.
 */
sealed trait TokenType {
  def value: String
}

case object TokenTypeString extends TokenType {
  override val value: String = "string"
}

case object TokenTypeNumeric extends TokenType {
  override val value: String = "numeric"
}

case object TokenTypeTemporal extends TokenType {
  override val value: String = "temporal"
}

case object TokenTypeStructured extends TokenType {
  override val value: String = "structured"
}

case object TokenTypeBinary extends TokenType {
  override val value: String = "binary"
}

case object TokenTypeNull extends TokenType {
  override val value: String = "null"
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 * Case class provides structural equality, pattern matching, and copy semantics.
 */
case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   */
  def withMetadata(entries: (String, Any)*): Token = {
    val newMeta = metadata ++ entries.toMap
    Token(value, tokenType, newMeta)
  }
}

/**
 * Mutable batch of tokens.
 * Only used for scenarios requiring mutability; prefer immutable Token values.
 */
class MutableTokenBatch {
  private val tokens: mutable.Buffer[Token] = mutable.Buffer.empty[Token]
  private var processed: Boolean = false

  /**
   * Add a token to the batch.
   * @throws IllegalStateException if batch has already been processed
   */
  def add(token: Token): Unit = {
    if (processed) {
      throw new IllegalStateException("Batch already processed")
    }
    tokens.append(token)
  }

  /**
   * Mark batch as processed, preventing further additions.
   */
  def markProcessed(): Unit = {
    processed = true
  }

  /**
   * Get all tokens in the batch.
   */
  def getAll: Vector[Token] = tokens.toVector

  /**
   * Check if batch is processed.
   */
  def isProcessed: Boolean = processed
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can return subtypes.
 * Variance annotation +T allows safe covariance for read-only operations.
 */
class TokenContainer[+T](items: Iterable[T]) {
  private val itemsVec: Vector[T] = items.toVector

  def getAll: Vector[T] = itemsVec

  def mapTokens[U](func: T => String): Vector[String] = {
    itemsVec.map(func)
  }

  def size: Int = itemsVec.size
}

/**
 * Contravariant sink - can accept supertypes.
 * Variance annotation -T allows safe contravariance for write-only operations.
 */
class TokenSink[-T] {
  private val received: mutable.Buffer[Any] = mutable.Buffer.empty[Any]

  def receive(item: T): Unit = {
    received.append(item)
  }

  def drain(): Vector[Any] = {
    val result = received.toVector
    received.clear()
    result
  }

  def size: Int = received.size
}

/**
 * Invariant handler - exact type matching required.
 * No variance annotations needed for invariant operations.
 */
class BivariantHandler[T](default: T) {
  private var value: T = default

  def get: T = value

  def set(newValue: T): Unit = {
    value = newValue
  }

  def transform(func: T => T): T = {
    value = func(value)
    value
  }
}

// ============================================================================
// Tokenizer Hierarchy
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 * Provides template for concrete tokenizer implementations.
 */
abstract class BaseTokenizer[T] {
  /**
   * Convert value to token.
   */
  def tokenize(value: T): Token

  /**
   * Lazy tokenization of multiple values.
   * Returns an iterator for memory-efficient processing of large datasets.
   */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

/**
 * Tokenizer for string and bytes types.
 */
class StringTokenizer(
    encoding: String = "utf-8",
    normalizer: String => String = identity
) extends BaseTokenizer[String] {

  def tokenize(value: String): Token = {
    val normalized = normalizer(value)
    Token(normalized, TokenTypeString)
  }

  /**
   * Tokenize bytes by first decoding to string.
   */
  def tokenizeBytes(bytes: Array[Byte]): Token = {
    val strValue = new String(bytes, encoding)
    tokenize(strValue)
  }
}

/**
 * Tokenizer for numeric types with precision handling.
 */
class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  def tokenize(value: Any): Token = {
    val strValue = value match {
      case bd: BigDecimal =>
        String.format(s"%.${precision}f", bd.toDouble)
      case d: Double =>
        String.format(s"%.${precision}f", d)
      case f: Float =>
        String.format(s"%.${precision}f", f)
      case i: Int =>
        i.toString
      case l: Long =>
        l.toString
      case other =>
        other.toString
    }
    Token(strValue, TokenTypeNumeric, Map("original_type" -> value.getClass.getSimpleName))
  }
}

/**
 * Tokenizer for date/time types.
 */
class TemporalTokenizer(customFormat: Option[String] = None) extends BaseTokenizer[Any] {

  private val isoFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: Any): Token = {
    val formatter = customFormat match {
      case Some(fmt) => DateTimeFormatter.ofPattern(fmt)
      case None =>
        value match {
          case _: LocalDateTime => isoFormatter
          case _: LocalDate => dateFormatter
          case _ => isoFormatter
        }
    }

    val strValue = value match {
      case dt: LocalDateTime => dt.format(formatter)
      case d: LocalDate => d.format(formatter)
      case other => other.toString
    }

    Token(strValue, TokenTypeTemporal)
  }
}

// ============================================================================
// Universal Tokenizer with Type Dispatch
// ============================================================================

/**
 * Tokenizer that handles multiple types.
 * Uses pattern matching for runtime type dispatch, replacing Python's isinstance checks.
 */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  /**
   * Dispatch to appropriate tokenizer based on runtime type.
   * Pattern matching ensures type safety and exhaustiveness checking.
   */
  def tokenize(value: Any): Token = {
    value match {
      case null =>
        Token("NULL", TokenTypeNull)

      case s: String =>
        stringTokenizer.tokenize(s)

      case b: Array[Byte] =>
        stringTokenizer.tokenizeBytes(b)

      case i: Int =>
        numericTokenizer.tokenize(i)

      case l: Long =>
        numericTokenizer.tokenize(l)

      case f: Float =>
        numericTokenizer.tokenize(f)

      case d: Double =>
        numericTokenizer.tokenize(d)

      case bd: BigDecimal =>
        numericTokenizer.tokenize(bd)

      case dt: LocalDateTime =>
        temporalTokenizer.tokenize(dt)

      case d: LocalDate =>
        temporalTokenizer.tokenize(d)

      case t: Tokenizable =>
        Token(t.toToken(), TokenTypeStructured)

      case other =>
        Token(other.toString, TokenTypeString, Map("fallback" -> true))
    }
  }
}

// ============================================================================
// Tokenizable Protocol (Scala version of Python Protocol)
// ============================================================================

/**
 * Structural type for objects that can be converted to token strings.
 * In Scala, we use a simple trait to define the contract.
 */
trait Tokenizable {
  def toToken(): String
}

// ============================================================================
// Token Registry with Complex Nested Generics
// ============================================================================

/**
 * Registry with complex nested generic types.
 * Combines mutable collections with generics for flexible token handling.
 */
class TokenRegistry[T] {
  private val registry: mutable.Map[String, TokenContainer[T]] = mutable.Map.empty
  private val handlers: mutable.Buffer[T => Option[Token]] = mutable.Buffer.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry.put(key, container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers.append(handler)
  }

  /**
   * Process all items in a container through all handlers.
   * Returns tokens or None for items without matching handlers.
   */
  def process(key: String): Vector[Option[Token]] = {
    registry.get(key) match {
      case None => Vector.empty
      case Some(container) =>
        container.getAll.map { item =>
          handlers.collectFirst {
            case handler if handler(item).nonEmpty => handler(item).get
          }
        }
    }
  }
}

