/**
 * Functor for tokens - supports map and flatMap operations.
 */
class TokenFunctor[T](protected val value: T) {
  def map[U](func: T => U): TokenFunctor[U] = {
    new TokenFunctor(func(value))
  }

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = {
    func(value)
  }

  def getOrElse(default: T): T = {
    value match {
      case null => default
      case v => v
    }
  }

  def get: T = value
}

/**
 * Extended monad operations for tokens.
 */
class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    new TokenMonad(funcWrapped.get(value))
  }
