/**
 * Tokenizer for JSON structures with recursive types.
 * Handles nested objects and arrays with recursive pattern matching.
 */
class JsonTokenizer(pretty: Boolean = false) {

  /**
   * Tokenize a JSON value (Map, List, or primitive).
   */
  def tokenize(value: JsonValue): Token = {
    val jsonStr = formatJson(value)
    Token(jsonStr, TokenTypeStructured, Map("json" -> true))
  }

  /**
   * Extract and tokenize a value at a JSON path.
   * Path format: "key1.key2.0.key3" for nested navigation.
   */
  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.")
    var current: Any = value

    for (part <- parts) {
      current = current match {
        case map: Map[String, Any] @unchecked if map.contains(part) =>
          map(part)
        case list: Vector[Any] if part.forall(_.isDigit) =>
          val idx = part.toInt
          if (idx >= 0 && idx < list.size) list(idx) else return None
        case _ => return None
      }
    }

    Some(tokenize(current.asInstanceOf[JsonValue]))
  }

  private def formatJson(value: JsonValue): String = {
    // Simple JSON serialization without external library
    value match {
      case null => "null"
      case s: String => s""""$s""""
      case b: Boolean => b.toString
      case n: Number => n.toString
      case map: Map[String, Any] @unchecked =>
        val entries = map.map { case (k, v) => s""""$k":${formatJson(v.asInstanceOf[JsonValue])}""" }
        if (pretty) {
          "{\n  " + entries.mkString(",\n  ") + "\n}"
        } else {
          "{" + entries.mkString(",") + "}"
        }
      case list: Vector[Any] =>
        val items = list.map(v => formatJson(v.asInstanceOf[JsonValue]))
        if (pretty) {
          "[\n  " + items.mkString(",\n  ") + "\n]"
        } else {
          "[" + items.mkString(",") + "]"
        }
      case _ => value.toString
    }
  }
}

