// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 * Fundamental tokenization operation used in NLP and text processing.
 */
class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {

  private val punctuation: Set[Char] = Set(".,!?;:'\"()[]{}".toCharArray: _*)

  /**
   * Process a single word into a token string.
   * Applies filtering and normalization based on configuration.
   */
  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.filter(c => !punctuation.contains(c))
    }

    if (lowercase) {
      processed = processed.toLowerCase()
    }

    if (processed.length < minLength) {
      return None
    }

    maxLength match {
      case Some(max) if processed.length > max =>
        processed = processed.substring(0, max)
      case _ =>
    }

    if (processed.isEmpty) None else Some(processed)
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): Vector[Token] = {
    val words = text.split("\\s+")
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          processed,
          TokenTypeString,
          Map("position" -> i, "original" -> word)
        )
      }
    }.toVector
  }

  /**
   * Split text by whitespace and return list of token strings.
   * Convenience method that returns just the string values.
   */
  def tokenizeToStrings(text: String): Vector[String] = {
    tokenize(text).map(_.value)
  }

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): Vector[(String, Int, Int)] = {
    val words = text.split("\\s+")
    var currentPos = 0
    val result = mutable.Buffer.empty[(String, Int, Int)]

    for (word <- words) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result.append((processed, start, end))
      }

      currentPos = end
    }

    result.toVector
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int = {
    tokenize(text).length
  }
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating customized tokenizers.
 * Enables method chaining with proper type bounds.
 */
class TokenizerBuilder[T] {
  private var normalizers: Vector[String => String] = Vector.empty
  private var validators: Vector[T => Boolean] = Vector.empty
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators = validators :+ validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ entries.toMap
    this
  }

  /**
   * Build the final tokenizer function.
   * Returns a function that validates, normalizes, and tokenizes values.
   * @throws IllegalArgumentException if validation fails
   */
  def build(): T => Token = { value =>
    // Validate
    validators.foreach { validator =>
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for $value")
      }
    }

    // Convert to string
    var strValue = value.toString

    // Normalize
    normalizers.foreach { normalizer =>
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenTypeString, metadata)
  }
}

// ============================================================================
// Factory Functions and Utility Methods
// ============================================================================

/**
